BBCAP_SMODS = ["ASOE", "ASOF", "ASOG", "ASOH"]


def use_bbcap(occurrences, enb_ent_config, execution_config, pddb_topology):
    if 'smods' in enb_ent_config:
        for smod_id in enb_ent_config['smods'].keys():
            if 'type' in enb_ent_config['smods'][smod_id]:
                if enb_ent_config['smods'][smod_id]['type'] in BBCAP_SMODS:
                    occurrences['BBCAP'] = 1
